// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public {
        c = new Owned();
    }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != c.owner());

        bool reverted;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted);
    }
}
